/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
/// <param name = "_fieldId">fieldId</param>
public void modifiedField(fieldId _fieldId)
{

    switch (_fieldId)
    {
        case fieldNum(InventQualityOrderLine, AVAInventQualityOrderLineResultReal):
            int lineNumDecimals;

            lineNumDecimals = this.setDecimal();

            this.AVAInventQualityOrderLineResultReal = decround(this.AVAInventQualityOrderLineResultReal, lineNumDecimals);

            break;
    }
    next modifiedField(_fieldId);

}

/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
/// <returns>integer</returns>
[SysClientCacheDataMethodAttribute]
public display int avaDisplayResultQty()
{
    InventQualityOrderLineResults  inventQualityOrderLineResults;
    int res = 0;

    select sum(TestResultQuantity) from inventQualityOrderLineResults
                where   inventQualityOrderLineResults.QualityOrderId        == this.QualityOrderId
                     && inventQualityOrderLineResults.TestId                == this.TestId
                     && inventQualityOrderLineResults.TestSequence          == this.TestSequence
                     && inventQualityOrderLineResults.TestResultQuantity     > 0;
    res = inventQualityOrderLineResults.TestResultQuantity;

    return res;
}
